solution:
pub type DivisionResult = enum {
  Success(quotient: Int),
  Error(message: Str),
}
  invariant: match this {
    DivisionResult::Error(m) => m.len() > 0,
    DivisionResult::Success(_) => true,
  };

fn safe_divide(a: Int, b: Int) -> DivisionResult {
  if b == 0 { return DivisionResult::Error("division by zero"); }
  return DivisionResult::Success(a / b);
}

fn main() -> Int {
  match safe_divide(10, 2) {
    DivisionResult::Success(q) => return q,
    DivisionResult::Error(_) => return 0,
  }
}
